using SlideKit.Dialogs;
namespace SlideKit;
public static class LayoutManager
{
    public static void MatrixLayout() { var a = AddInModule.PowerPointApp; if (a?.ActivePresentation == null) return; try { var sel = a.ActiveWindow.Selection; if (sel.Type != 2 || sel.ShapeRange.Count == 0) { W("Select 1+ shapes."); return; } using var d = new MatrixLayoutDialog(); if (d.ShowDialog() != System.Windows.Forms.DialogResult.OK) return; dynamic sr = sel.ShapeRange; int n = sr.Count, cols = d.Columns; float hG = d.HorizontalGap, vG = d.VerticalGap, mw = 0, mh = 0; for (int i = 1; i <= n; i++) { mw = Math.Max(mw, sr[i].Width); mh = Math.Max(mh, sr[i].Height); } float sl = sr[1].Left, st = sr[1].Top; for (int i = 1; i <= n; i++) { int c = (i - 1) % cols, r = (i - 1) / cols; sr[i].Left = sl + c * (mw + hG); sr[i].Top = st + r * (mh + vG); } } catch { } }
    public static void CircularLayout() { var a = AddInModule.PowerPointApp; if (a?.ActivePresentation == null) return; try { var sel = a.ActiveWindow.Selection; if (sel.Type != 2 || sel.ShapeRange.Count == 0) { W("Select 1+ shapes."); return; } using var d = new CircularLayoutDialog(); if (d.ShowDialog() != System.Windows.Forms.DialogResult.OK) return; dynamic sr = sel.ShapeRange; int n = sr.Count; float r = d.Radius, sa = d.StartAngle, cx = 0, cy = 0; bool cw = d.Clockwise; for (int i = 1; i <= n; i++) { cx += sr[i].Left + sr[i].Width / 2; cy += sr[i].Top + sr[i].Height / 2; } cx /= n; cy /= n; double step = 2 * Math.PI / n, srR = sa * Math.PI / 180; int dir = cw ? -1 : 1; for (int i = 1; i <= n; i++) { double ang = srR + dir * (i - 1) * step; sr[i].Left = (float)(cx + r * Math.Cos(ang)) - sr[i].Width / 2; sr[i].Top = (float)(cy + r * Math.Sin(ang)) - sr[i].Height / 2; } } catch { } }
    static void W(string m) => System.Windows.Forms.MessageBox.Show(m, "iSlide", System.Windows.Forms.MessageBoxButtons.OK, System.Windows.Forms.MessageBoxIcon.Warning);
}
